const menuButton=document.querySelector('.menu-toggle');
const nav=document.querySelector('.nav');
menuButton?.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'Close':'Menu';nav.classList.toggle('open',open)});
function closeMenu(){menuButton?.setAttribute('aria-expanded','false');if(menuButton)menuButton.textContent='Menu';nav?.classList.remove('open')}
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeMenu();menuButton.focus()}});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}
const filters=[...document.querySelectorAll('.filter')];
const cards=[...document.querySelectorAll('.work-grid .project-card')];
function filterProjects(value,update=true){if(!filters.some(b=>b.dataset.filter===value))value='All';filters.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===value)));let count=0;cards.forEach(c=>{c.hidden=value!=='All'&&c.dataset.category!==value;if(!c.hidden)count++});const status=document.querySelector('.work-count');if(status)status.textContent=`${count} ${count===1?'project':'projects'}${value==='All'?'':` / ${value}`}`;if(update){const u=new URL(location);if(value==='All')u.searchParams.delete('category');else u.searchParams.set('category',value);history.replaceState(null,'',u)}}
filters.forEach(b=>b.addEventListener('click',()=>filterProjects(b.dataset.filter)));if(filters.length)filterProjects(new URL(location).searchParams.get('category')||'All',false);
const form=document.querySelector('#brief-form');
form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const name=String(data.get('name')).trim();const company=String(data.get('company')).trim();const service=String(data.get('service'));const body=`Hi Revolio,\n\nI'm ${name}${company?` from ${company}`:''}.\n\nI'm interested in: ${service}\n\n${String(data.get('brief')).trim()}\n\nReply to: ${String(data.get('email')).trim()}\n\nThanks,\n${name}`;const link=document.querySelector('#email-draft');link.href=`mailto:info@revolio.in?subject=${encodeURIComponent(`Project enquiry: ${service}`)}&body=${encodeURIComponent(body)}`;const result=document.querySelector('#form-result');result.hidden=false;result.focus();link.focus()});
